// R4i-cowork CW1 (research-ext/X2 CW-1; cowork-session-actions, transcript-16): the 2.42304.0 Cowork session action
// originals generated by scripts/extract-cowork-session-actions.mjs — c21f11e6d cO / lO / uO / dO / dk, cb1e253a0 vm / ym,
// shared-0 By, preload-helper's error-text tag — and the host side in src/source-cowork-session-actions-adapters.jsx.
// The generated modules are plain ESM and are imported directly; the adapter goes through Vite SSR (no HMR, no
// WebSocket, no port). No browser, no DOM, no network, no IPC, no real session.
import test, { before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createServer } from 'vite';
import { extractCoworkSessionActions } from '../scripts/extract-cowork-session-actions.mjs';
import { LocalRewindRefusal } from '../src/generated/cowork-session-actions/refusal.mjs';
import { hasRewindBridge, rewindLocalSession } from '../src/generated/cowork-session-actions/rewind-bridge.mjs';
import { remoteRewindRejectionMessage, localRewindRefusalMessage, rewindFailureMessage, rewindOutcomeToast,
  lastHumanBubbleWhenRewindable } from '../src/generated/cowork-session-actions/rewind-messages.mjs';

const app = path.resolve(import.meta.dirname, '..');
const generated = path.join(app, 'src/generated/cowork-session-actions');
const reference = path.resolve(app, '../reference/installed-2.42304.0-20261017/ion-dist/assets/v1');
const official = name => fs.readFileSync(path.join(reference, name), 'utf8');
const count = (text, needle) => text.split(needle).length - 1;
// The minified chunks spell ’ as the escape ’.
const minified = text => text.replaceAll('’', '\\u2019');
// The intl the originals receive: echoes the English default and records the id it was asked for.
const asked = [];
const intl = { formatMessage: ({ defaultMessage, id }) => { asked.push(id); return defaultMessage; } };

let server, A;
before(async () => {
  server = await createServer({ configFile: false, root: app,
    server: { middlewareMode: true, hmr: false, ws: false, watch: null }, appType: 'custom', logLevel: 'error' });
  A = await server.ssrLoadModule('/src/source-cowork-session-actions-adapters.jsx');
});
after(async () => { await server?.close(); });

test('CW1 generator: --check passes and the output is pinned to the installed 2.42304.0 chunks', async () => {
  const manifest = await extractCoworkSessionActions({ check: true });
  assert.equal(manifest.referenceVersion, '2.42304.0');
  assert.equal(manifest.adapterModule, 'src/source-cowork-session-actions-adapters.jsx');
  assert.deepEqual(manifest.modules.map(m => m.target), ['refusal.mjs', 'error-text.mjs', 'rewind-bridge.mjs', 'rewind-messages.mjs']);
  assert.deepEqual(fs.readdirSync(generated).sort(), ['error-text.mjs', 'manifest.json', 'refusal.mjs', 'rewind-bridge.mjs', 'rewind-messages.mjs']);
  const by = target => manifest.modules.find(m => m.target === target);
  assert.deepEqual(by('refusal.mjs').exports, { By: 'LocalRewindRefusal' });
  assert.deepEqual(by('rewind-bridge.mjs').exports, { vm: 'hasRewindBridge', ym: 'rewindLocalSession' });
  assert.deepEqual(by('rewind-messages.mjs').exports, { cO: 'remoteRewindRejectionMessage', lO: 'localRewindRefusalMessage',
    uO: 'rewindFailureMessage', dO: 'rewindOutcomeToast', dk: 'lastHumanBubbleWhenRewindable' });
  assert.deepEqual(by('rewind-messages.mjs').bindings.map(b => b.name), ['cO', 'lO', 'uO', 'dO', 'dk']);
  assert.deepEqual(by('rewind-bridge.mjs').bindings.map(b => b.name), ['gm', 'vm', 'ym']);
  // Every import resolves to a module generated here (no view-tabs compressed names, D1/D46).
  for (const m of manifest.modules) for (const i of m.imports) assert.equal(i.kind, 'generated', `${m.target} ${i.local}`);
  assert.deepEqual(by('rewind-messages.mjs').imports, [{ local: 'ke', from: './refusal.mjs', name: 'LocalRewindRefusal',
    via: 'shared-0-ByI5P0CP.js:Ch', kind: 'generated', original: 'By' }]);
  for (const m of manifest.modules) assert.equal(m.sha256, (await import('node:crypto')).createHash('sha256')
    .update(fs.readFileSync(path.join(generated, m.target), 'utf8')).digest('hex'), m.target);
});

test('CW1 root features: the installed chunks still carry the originals at their bindings', () => {
  const c21 = official('c21f11e6d-Bd0v2A97.js'), cb1 = official('cb1e253a0-DQ4zAGBV.js'), s0 = official('shared-0-ByI5P0CP.js');
  assert.equal(count(c21, 'id:"EMw1vE8dOU"'), 1);
  assert.equal(count(c21, 'id:"JAqfKwYq8j"'), 1);
  assert.equal(count(c21, 'CoworkSessionView edit rewind timeout'), 1);
  assert.equal(count(c21, 'function dO(e,t,n){'), 1);
  assert.equal(count(c21, 'function dk(e){if(e.canRewindToMessage)return e.findLastHumanBubble()}'), 1);
  assert.equal(count(c21, 'Ch as ke'), 1);
  assert.equal(count(cb1, 'e?.rewindV2??e?.rewind'), 1);
  assert.equal(count(cb1, 'rewind IPC unavailable'), 2);
  assert.equal(count(cb1, 'vm as y'), 1);
  assert.equal(count(cb1, 'ym as b'), 1);
  assert.equal(count(s0, 'e.Dead="dead",e.NoText="no_text",e.Unsupported="unsupported",e.Unknown="unknown"'), 1);
  assert.equal(count(s0, 'By as Ch'), 1);
  // The generated root modules carry the same features.
  const messages = fs.readFileSync(path.join(generated, 'rewind-messages.mjs'), 'utf8');
  for (const id of ['QfDweriZQj', 'N4pAEIJK4/', 'K1/egsMFpR', 'cnZntAZvlD', 'TW8yay5oV+', 'pcv56liZj9', 'YmzbNCp+kq', '/FZxzzWOs5',
    'SC1NI+O8Y4', 'N6n//LvbO8', 'EMw1vE8dOU', 'fUE4seXTv0', 'JAqfKwYq8j', 'SgdArTNAT/', 'kvjiUWTVfc'])
    assert.equal(count(messages, `id: "${id}"`), 1, id);
  assert.deepEqual({ ...LocalRewindRefusal }, { Dead: 'dead', NoText: 'no_text', Unsupported: 'unsupported', Unknown: 'unknown' });
});

// dO, table-driven: every outcome × surface × refusal × isRemoteSession against the English original.
const T = {
  timeout: 'Couldn’t confirm the rewind. If your message clears, re-send it from the composer.',
  restart: 'Couldn’t restart from this message. Try again.',
  refusal_retry: 'Couldn’t retry. Try again.',
  edit: 'Couldn’t edit this message. Try again.',
  dead: 'This message can’t be edited or restarted from anymore. Send what you need as a new message instead.',
  no_text: 'Messages without text, like ones with only images, can’t be edited or restarted from. Send what you need as a new message instead.',
  unsupported: 'Messages in this task can’t be edited or restarted from. Send what you need as a new message instead.',
  remoteEmpty: 'This message can’t be restarted from here.',
  localEmpty: 'Couldn’t restart from this message. Try again, or pick another message.',
  'turn running': 'Claude is still working on this task. Stop the task or let it finish, then try again.',
  'commands queued': 'This task has queued messages waiting to send. Let them send, then try again.',
  'stale target': 'Right now this task can only be edited or restarted from its latest message. If a newer message isn’t shown here, reload the page.',
  'unseen later turn': 'This task has a newer message than the ones shown here, possibly sent from another window. Reload the page, then try again.',
  'target not found': 'This message can’t be edited or restarted from: it was sent while Claude was still working on the previous one, or it is from an earlier part of a long task that has since been condensed.',
  rejectedDefault: 'Couldn’t edit or restart from this message right now. Try again in a moment.',
};
const surfaces = ['restart', 'edit', 'refusal_retry'];
const err = Object.assign(Error('boom'), { reason: 'turn running' });
const cases = [];
for (const isRemoteSession of [false, true]) for (const surface of surfaces) {
  const kind = surface === 'edit' ? 'edit rewind' : 'rewind';
  cases.push([{ kind: 'sent' }, surface, isRemoteSession, null]);
  cases.push([{ kind: 'timeout' }, surface, isRemoteSession, { message: T.timeout, options: { messageForLogging:
    surface === 'edit' ? 'CoworkSessionView edit rewind timeout' : 'CoworkSessionView rewind confirm timeout' } }]);
  for (const reason of ['turn running', 'commands queued', 'stale target', 'unseen later turn', 'target not found', 'other'])
    cases.push([{ kind: 'rejected', error: { reason } }, surface, isRemoteSession, { message: T[reason] ?? T.rejectedDefault,
      options: { error: { reason }, messageForLogging: `CoworkSessionView ${kind} rejected by CLI` } }]);
  cases.push([{ kind: 'error', error: err }, surface, isRemoteSession, { message: T[surface], options: { error: err,
    messageForLogging: surface === 'refusal_retry' ? 'CoworkSessionView refusal rewind failed' : `CoworkSessionView ${kind} failed` } }]);
  for (const refusal of ['dead', 'no_text', 'unsupported'])
    cases.push([{ kind: 'empty', refusal }, surface, isRemoteSession, { message: T[refusal], options: {
      messageForLogging: `CoworkSessionView ${surface === 'edit' ? 'edit' : 'local'} rewind refused: ${refusal}` } }]);
  for (const refusal of [undefined, 'unknown']) {
    const expected = surface === 'refusal_retry' ? { message: T.refusal_retry, options: { messageForLogging: 'CoworkSessionView refusal rewind returned empty' } }
      : surface === 'edit' ? { message: T.edit, options: { messageForLogging: 'CoworkSessionView edit rewind returned empty' } }
      : isRemoteSession ? { message: T.remoteEmpty, options: { messageForLogging: 'CoworkSessionView remote rewind target not rewindable' } }
      : { message: T.localEmpty, options: { messageForLogging: 'CoworkSessionView local rewind target not rewindable' } };
    cases.push([{ kind: 'empty', ...(refusal ? { refusal } : {}) }, surface, isRemoteSession, expected]);
  }
}

test('CW1 dO: every outcome maps to the original toast, text compared with the English original', () => {
  const c21 = official('c21f11e6d-Bd0v2A97.js');
  for (const text of Object.values(T)) assert.equal(count(c21, minified(text)), 1, text);
  assert.equal(cases.length, 2 * 3 * 14);
  for (const [outcome, surface, isRemoteSession, expected] of cases)
    assert.deepEqual(rewindOutcomeToast(outcome, { surface, isRemoteSession }, intl), expected,
      `${outcome.kind}/${outcome.refusal ?? outcome.error?.reason ?? ''} ${surface} remote=${isRemoteSession}`);
  // Each message the originals format is asked for by its official id.
  asked.length = 0;
  rewindOutcomeToast({ kind: 'timeout' }, { surface: 'restart' }, intl);
  rewindOutcomeToast({ kind: 'empty' }, { surface: 'restart', isRemoteSession: true }, intl);
  rewindOutcomeToast({ kind: 'empty' }, { surface: 'restart', isRemoteSession: false }, intl);
  rewindOutcomeToast({ kind: 'error', error: err }, { surface: 'refusal_retry' }, intl);
  assert.deepEqual(asked, ['JAqfKwYq8j', 'SgdArTNAT/', 'kvjiUWTVfc', 'EMw1vE8dOU']);
});

test('CW1 cO / lO / uO / dk directly', () => {
  assert.equal(remoteRewindRejectionMessage('stale target', intl), T['stale target']);
  assert.equal(remoteRewindRejectionMessage(undefined, intl), T.rejectedDefault);
  assert.equal(localRewindRefusalMessage(LocalRewindRefusal.Dead, intl), T.dead);
  assert.equal(localRewindRefusalMessage(LocalRewindRefusal.Unknown, intl), undefined);
  assert.equal(localRewindRefusalMessage(undefined, intl), undefined);
  assert.equal(rewindFailureMessage('restart', intl), T.restart);
  assert.equal(rewindFailureMessage('other', intl), undefined);
  const bubble = { text: 'hi', uuid: 'u1' };
  assert.equal(lastHumanBubbleWhenRewindable({ canRewindToMessage: true, findLastHumanBubble: () => bubble }), bubble);
  assert.equal(lastHumanBubbleWhenRewindable({ canRewindToMessage: false, findLastHumanBubble: () => bubble }), undefined);
});

test('CW1 vm / ym: bridge detection, rewindV2 normalisation, legacy rewind, missing bridge', async () => {
  assert.equal(hasRewindBridge(undefined), false);
  assert.equal(hasRewindBridge({}), false);
  assert.equal(hasRewindBridge({ rewind() {} }), true);
  assert.equal(hasRewindBridge({ rewindV2() {} }), true);
  const calls = [];
  const v2 = refusal => ({ async rewindV2(...args) { calls.push(args); return { prefill: 'again', refusal }; } });
  assert.deepEqual(await rewindLocalSession(v2(undefined), 's1', 'u1'), { prefill: 'again', refusal: undefined });
  assert.deepEqual(calls, [['s1', 'u1']]);
  assert.deepEqual(await rewindLocalSession(v2('dead'), 's1', 'u1'), { prefill: 'again', refusal: 'dead' });
  assert.deepEqual(await rewindLocalSession(v2('something-new'), 's1', 'u1'), { prefill: 'again', refusal: 'unknown' });
  assert.deepEqual(await rewindLocalSession({ async rewind() { return 'old'; } }, 's1', 'u1'), { prefill: 'old' });
  assert.deepEqual(await rewindLocalSession({ async rewind() { return null; } }, 's1', 'u1'), { prefill: undefined });
  await assert.rejects(rewindLocalSession(null, 's1', 'u1'), e => {
    assert.equal(e.message, 'rewind IPC unavailable');
    assert.deepEqual(e[Symbol.for('ant.o11y.errorText')], { text: 'rewind IPC unavailable', kind: 'literal' });
    return true;
  });
});

test('CW1 adapter: local-only intl over electron/i18n, the host bridge, D17 remote off', async () => {
  assert.equal(A.COWORK_REMOTE_SESSIONS, false);
  assert.equal(A.coworkRewindBridge(undefined), null);
  assert.equal(A.coworkCanRewind(A.coworkRewindBridge(undefined)), false);
  const seen = [];
  const bridge = A.coworkRewindBridge(async (sessionId, uuid) => { seen.push([sessionId, uuid]); return { prefill: 'p', refusal: 'bogus' }; });
  assert.equal(A.coworkCanRewind(bridge), true);
  assert.deepEqual(await A.coworkRewind(bridge, 'cw-1', 'm-1'), { prefill: 'p', refusal: 'unknown' });
  assert.deepEqual(seen, [['cw-1', 'm-1']]);
  // isRemoteSession is always false: an empty restart is the local text.
  assert.deepEqual(A.coworkRewindToast({ kind: 'empty' }, 'restart'),
    { message: T.localEmpty, options: { messageForLogging: 'CoworkSessionView local rewind target not rewindable' } });
  assert.equal(A.coworkRewindToast({ kind: 'sent' }, 'edit'), null);
  assert.equal(A.coworkRefusalMessage('no_text'), T.no_text);
  assert.equal(A.coworkFailureMessage('refusal_retry'), T.refusal_retry);
  assert.equal(typeof A.lastHumanBubbleWhenRewindable, 'function');
});
